SELECT TNA.*,audi.*,target.targetName,target.targetDesc FROM TBL_NBSJ_OPERATE TNA LEFT JOIN TBL_NBSJ_AUTHORIZATION auth ON TNA. AUTHID = auth. AUTHID LEFT JOIN TBL_NBSJ_AUDITPROGRAM audi ON audi.programid = auth.programid LEFT JOIN TBL_NBSJ_TARGETTYPE target ON target.targetId = audi.targetId LEFT JOIN TBL_NBSJ_TEAMSTAFF team on team.id = auth.TEAMSTAFFID
1=1
and audi.businessType like concat(concat('%',#{tblNbsjOperateVo.businessType}),'%')
AND auth.projectid = #{tblNbsjOperateVo.projectId}
AND team.staffid = #{tblNbsjOperateVo.staffid}
AND target.targetId = #{tblNbsjOperateVo.targetId}
ORDER BY TNA.OPERATEID DESC

SELECT TNA.*,audi.*,target.targetName,target.targetDesc FROM TBL_NBSJ_OPERATE TNA LEFT JOIN TBL_NBSJ_AUTHORIZATION auth ON TNA. AUTHID = auth. AUTHID LEFT JOIN TBL_NBSJ_AUDITPROGRAM audi ON audi.programid = auth.programid LEFT JOIN TBL_NBSJ_TARGETTYPE target ON target.targetId = audi.targetId LEFT JOIN TBL_NBSJ_TEAMSTAFF team on team.id = auth.TEAMSTAFFID
auth.projectid = #{projectid}
AND target.targetId = #{targetId}
AND audi.BUSINESSTYPE like concat(concat('%',#{businessType}),'%')
ORDER BY TNA.OPERATEID DESC
